    assert_eq!(s.run(json!({"Command": "Tick", "Seconds": 0, "Extra": 1})), json!({"ok": true, "Now": 5}));
    assert_eq!(s.code(json!({"Command": "Tick", "Seconds": null})), "MissingParameter");
    for bad in [json!(30.0), json!("1"), json!(-1), json!(1209601), json!(true)] {
        assert_eq!(s.code(json!({"Command": "Tick", "Seconds": bad})), "InvalidParameterValue");
    }
