    // Queue lookup beats the command's own rules, whatever the name looks like.
    assert_eq!(s.code(json!({"Command": "SendMessage", "QueueName": "!?", "Body": "x"})), "QueueDoesNotExist");
    // CreateQueue checks the name before the other values.
    let response = s.run(json!({"Command": "CreateQueue", "QueueName": "a b", "Attributes": {"Fifo": "x"}}));
    assert_eq!(response["error"]["code"], json!("QueueNameInvalid"));
    assert_eq!(s.code(json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": {"Bogus": 1}})), "InvalidParameterValue");
    assert_eq!(s.code(json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": 3})), "InvalidParameterValue");
