    let lines: Vec<_> = out.lines().collect();
    assert_eq!(lines.len(), 2);
    assert!(lines[0].contains("InvalidRequest"));
    assert_eq!(lines[1], r#"{"ok":true,"QueueNames":[]}"#);
}

